var msg_payload = msg.payload;

if (msg_payload.scene_name) {
    var region_name = msg_payload.region_name;
    var timestamp = msg_payload.timestamp;
    var counts = msg_payload.counts;
    var count_keys = Object.keys(counts);

    count_keys.forEach(function (key) {
        var json_body = [
            { count: counts[key] + "i" },
            {
                location: msg_payload.scene_name || "Anthem",
                region: region_name,
                object: key
            }
        ];
        node.send({ payload: json_body, measurement: "region_obj_count_2", timestamp: timestamp });
    });

    var objects_exited = msg_payload.exited;
    var items_exited = objects_exited.length;
    if (items_exited > 0) {
        objects_exited.forEach(function (obj) {
            var json_body2 = [
                { dwell_time: parseFloat(obj.dwell.toFixed(2)) },
                {
                    location: msg_payload.scene_name || "Anthem",
                    region: region_name,
                    object: obj.object.category
                }
            ];
            node.send({ payload: json_body2, measurement: "region_obj_dwell_2", timestamp: timestamp });
        });
    }

    var pedestrian_noped_count = Number((counts || {}).pedestrian || 0);
    var vehicle_noped_count = Number((counts || {}).vehicle || 0);
    var jaywalking_detected = region_name === "NOPED" && pedestrian_noped_count > 0;
    var collision_count = jaywalking_detected ? vehicle_noped_count : 0;

    var collision_body = [
        {
            count: collision_count + "i",
            trigger: (collision_count > 0 ? 1 : 0) + "i"
        },
        {
            location: msg_payload.scene_name || "Anthem",
            region: "NOPED",
            object: "vehicle"
        }
    ];
    node.send({ payload: collision_body, measurement: "collision_events_2", timestamp: timestamp });
}
return null;

var msg_payload = msg.payload;

if (msg_payload.name === 'Intersection-Demo') {
    var timestamp = msg_payload.timestamp;
    // Handle pedestrian tracking data
    if (msg_payload.objects && Array.isArray(msg_payload.objects)) {
        msg_payload.objects.forEach(function (obj) {
            if (obj.category === "pedestrian" && ("lat_long_alt" in obj)) {
                // Calculate speed (velocity magnitude)
                var vel = obj.velocity || [0, 0, 0];
                var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1] + vel[2] * vel[2]);

                var json_body3 = [
                    {
                        pedid: obj.id,
                        latitude: obj.lat_long_alt ? obj.lat_long_alt[0] : 0,
                        longitude: obj.lat_long_alt ? obj.lat_long_alt[1] : 0,
                        heading: obj.heading || 0,
                        velocity: speed.toFixed(2)
                    },
                    {
                        location: msg_payload.name || msg_payload.scene_name || "Anthem"
                    }
                ];

                node.send({
                    payload: json_body3,
                    measurement: "pedestrian_loc",
                    timestamp: timestamp
                });
            }
        });
    }
}
return null;

var msg_payload = msg.payload;

var tripwire_name = msg_payload.tripwire_name;
var timestamp = msg_payload.timestamp;
var objects = msg_payload.objects || [];
var fs = global.get('fs');

var wrong_way_direction = {
    'NBLANE_START_TW': -1,
    'NBLANE_END_TW': -1,
    'SBLANE_START_TW': -1,
    'SBLANE_END_TW': -1,
    'EBLANE_START_TW': -1,
    'EBLANE_END_TW': -1,
    'WBLANE_START_TW': -1,
    'WBLANE_END_TW': -1
};

var bad_dir = wrong_way_direction[tripwire_name];
if (bad_dir === undefined) { return null; }

var lane = tripwire_name.replace('_START_TW', '').replace('_END_TW', '');

var ts = new Date();
try { ts = new Date(timestamp); } catch (e) {}
var dateStr = ts.toISOString().split("T")[0];
var timeStr = ts.toTimeString().split(" ")[0].replace(/:/g, "");

objects.forEach(function (obj) {
    if (obj.direction === bad_dir) {
        var vel = obj.velocity || [0, 0, 0];
        var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1]);

        if (speed < 0.5) { return; }

        var imageUrl = "";
        var frameUrl = "";
        var baseDir = `/images_data/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}`;

        if (obj.image_b64) {
            try {
                fs.mkdirSync(baseDir, { recursive: true });
                var imgName = `wrongway_${obj.id || 'unknown'}_${timeStr}.jpg`;
                fs.writeFileSync(`${baseDir}/${imgName}`, Buffer.from(obj.image_b64, "base64"));
                imageUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${imgName}`;
            } catch (err) {}
        }

        var f_b64 = obj.frame_b64 || msg_payload.frame_b64;
        if (f_b64) {
            try {
                fs.mkdirSync(baseDir, { recursive: true });
                var frameName = `wrongway_frame_${obj.id || 'unknown'}_${timeStr}.jpg`;
                fs.writeFileSync(`${baseDir}/${frameName}`, Buffer.from(f_b64, "base64"));
                frameUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${frameName}`;
            } catch (err) {}
        }

        var json_body = [
            {
                object_id: String(obj.uuid || obj.global_id || obj.id || 'unknown'),
                heading: obj.heading || 0,
                speed: parseFloat(speed.toFixed(2)),
                wrong_way: 1,
                event_url: imageUrl,
                frame_url: frameUrl
            },
            {
                location: msg_payload.scene_name || 'Anthem',
                region: lane,
                object: obj.category || 'vehicle'
            }
        ];

        node.send({
            payload: json_body,
            measurement: 'wrong_way_alert',
            timestamp: timestamp
        });
    }
});

return null;

var msg_payload = msg.payload;

var REGION_CONFIG = {
    'NBLANE':  { stall_threshold_sec: 60 },
    'SBLANE':  { stall_threshold_sec: 60 },
    'EBLANE':  { stall_threshold_sec: 60 },
    'WBLANE':  { stall_threshold_sec: 60 },
    'NOPED':   { stall_threshold_sec: 20 },
    'INTERSECTION': { stall_threshold_sec: 15 }
};

var SPEED_THRESHOLD = 0.5;
var CLEANUP_TIMEOUT_SEC = 60;
var fs = global.get('fs');

var tracker = flow.get('stalledVehicleTracker') || {};

var timestamp    = msg_payload.timestamp;
var region_name  = msg_payload.region_name || msg_payload.scene_name;
var objects      = msg_payload.objects || [];

if (!REGION_CONFIG[region_name]) { return null; }

var threshold_sec = REGION_CONFIG[region_name].stall_threshold_sec;
var now_sec       = parseFloat(timestamp);

var ts = new Date();
try { ts = new Date(timestamp * 1000); } catch (e) {}
var dateStr = ts.toISOString().split("T")[0];
var timeStr = ts.toTimeString().split(" ")[0].replace(/:/g, "");

objects.forEach(function (obj) {
    if (obj.category !== 'vehicle') { return; }

    var id  = obj.id;
    var vel = obj.velocity || [0, 0, 0];
    var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1]);

    if (!tracker[id]) {
        tracker[id] = {
            firstStationarySec: speed < SPEED_THRESHOLD ? now_sec : null,
            lastSeenSec:        now_sec,
            region:             region_name,
            alertSent:          false,
            speed:              parseFloat(speed.toFixed(2))
        };
    } else {
        var rec = tracker[id];
        rec.lastSeenSec = now_sec;
        rec.speed       = parseFloat(speed.toFixed(2));

        if (speed >= SPEED_THRESHOLD) {
            rec.firstStationarySec = null;
            rec.alertSent          = false;
            rec.region             = region_name;
        } else {
            if (rec.firstStationarySec === null) {
                rec.firstStationarySec = now_sec;
            }

            var stalled_duration_sec = now_sec - rec.firstStationarySec;

            if (stalled_duration_sec >= threshold_sec && !rec.alertSent) {
                rec.alertSent = true;

                var imageUrl = "";
                var frameUrl = "";
                var baseDir = `/images_data/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}`;

                if (obj.image_b64) {
                    try {
                        fs.mkdirSync(baseDir, { recursive: true });
                        var imgName = `stalled_${id}_${timeStr}.jpg`;
                        fs.writeFileSync(`${baseDir}/${imgName}`, Buffer.from(obj.image_b64, "base64"));
                        imageUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${imgName}`;
                    } catch (err) {}
                }

                if (msg_payload.frame_b64) {
                    try {
                        fs.mkdirSync(baseDir, { recursive: true });
                        var frameName = `stalled_frame_${id}_${timeStr}.jpg`;
                        fs.writeFileSync(`${baseDir}/${frameName}`, Buffer.from(msg_payload.frame_b64, "base64"));
                        frameUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${frameName}`;
                    } catch (err) {}
                }

                var json_body = [
                    {
                        stalled_duration: parseFloat(stalled_duration_sec.toFixed(2)),
                        speed:            rec.speed,
                        trigger:          1,
                        event_url:        imageUrl,
                        frame_url:        frameUrl
                    },
                    {
                        location:   msg_payload.scene_name || msg_payload.name || 'Anthem',
                        region:     region_name,
                        object:     'vehicle',
                        vehicle_id: String(id)
                    }
                ];
                node.send({
                    payload:     json_body,
                    measurement: 'stalled_vehicle_alert',
                    timestamp:   timestamp
                });
            }
        }
    }
});

Object.keys(tracker).forEach(function (id) {
    if ((now_sec - tracker[id].lastSeenSec) > CLEANUP_TIMEOUT_SEC) {
        delete tracker[id];
    }
});

flow.set('stalledVehicleTracker', tracker);
return null;

// === CONGESTION DETECTION LOGIC (Low average speed over n seconds) ===
var CONGESTION_CONFIG = {
    'NBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'SBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'EBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'WBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'INTERSECTION': { speed_threshold: 2.0, duration_sec: 10, min_vehicles: 3 }
};

var congTracker = flow.get('congestionTracker') || {};
var cfg = CONGESTION_CONFIG[region_name] || { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 };

var regVehicles = [];
var congFrameB64 = null;

objects.forEach(function (o) {
    if (o.category === 'vehicle') {
        var v = o.velocity || [0, 0, 0];
        var s = Math.sqrt(v[0] * v[0] + v[1] * v[1]);
        regVehicles.push(s);

        if (!congFrameB64) {
            if (o.frame_b64) { congFrameB64 = o.frame_b64; }
            else if (msg_payload.frame_b64) { congFrameB64 = msg_payload.frame_b64; }
        }
    }
});

if (!congTracker[region_name]) {
    congTracker[region_name] = { firstLowSpeedSec: null, alertSent: false };
}
var cState = congTracker[region_name];

if (regVehicles.length >= cfg.min_vehicles) {
    var totSpeed = regVehicles.reduce(function(a, b) { return a + b; }, 0);
    var avgSpeed = totSpeed / regVehicles.length;

    if (avgSpeed < cfg.speed_threshold) {
        if (cState.firstLowSpeedSec === null) {
            cState.firstLowSpeedSec = now_sec;
        }
        var congDurationSec = now_sec - cState.firstLowSpeedSec;

        if (congDurationSec >= cfg.duration_sec && !cState.alertSent) {
            cState.alertSent = true;

            var congFrameUrl = "";
            if (congFrameB64) {
                try {
                    var cBaseDir = `/images_data/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}`;
                    fs.mkdirSync(cBaseDir, { recursive: true });
                    var cFrameName = `congestion_frame_${region_name}_${timeStr}.jpg`;
                    fs.writeFileSync(`${cBaseDir}/${cFrameName}`, Buffer.from(congFrameB64, "base64"));
                    congFrameUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${cFrameName}`;
                } catch (err) {}
            }

            var congBody = [
                {
                    avg_speed:     parseFloat(avgSpeed.toFixed(2)),
                    dwell_time:    parseFloat(congDurationSec.toFixed(2)),
                    vehicle_count: regVehicles.length,
                    trigger:       1,
                    frame_url:     congFrameUrl
                },
                {
                    location: msg_payload.scene_name || msg_payload.name || 'Anthem',
                    region:   region_name,
                    object:   'vehicle'
                }
            ];

            node.send({
                payload:     congBody,
                measurement: 'congestion_events',
                timestamp:   timestamp
            });
        }
    } else {
        cState.firstLowSpeedSec = null;
        cState.alertSent = false;
    }
} else {
    cState.firstLowSpeedSec = null;
    cState.alertSent = false;
}

flow.set('congestionTracker', congTracker);
